package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** The person on the sheet with the typed name (case and surrounding spaces ignored), else a new one. */
public class ResolvePerson {
    public void resolve(@Val SheetResponse sheet, @Val PersonRequest request, PersonRepository repository,
            Out<Person> person, Out<QuickAddPerson> resolved) {
        Person found = repository.findByName(sheet.id(), request.name());
        boolean added = found == null;
        if (added) {
            found = repository.insert(sheet.id(), request.name(), request.grade());
        }
        person.set(found);
        resolved.set(new QuickAddPerson(found, added));
    }
}
package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

/** PERSON_ADDED, as the person form records it, when the quick-add created the person. */
public class RecordQuickAddPerson {
    public void record(@Val QuickAddPerson resolved, @Val ChangedBy by, Audit audit) {
        if (!resolved.added()) {
            return;
        }
        Person person = resolved.person();
        audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + by.name() + " name=" + person.getName()
                + " grade=" + person.getGrade());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Refuses a new claim (date blank: the sheet's entry date, else its today) whose due-by, its date plus the terms it would
 * get, falls inside a closed period.
 */
public class RefuseClosedNewDate {

    public void check(@Val Person person, @Val ClaimInput input, SheetRepository sheets,
            SettingRepository settings, PeriodRepository periods, HolidayRepository holidays) throws BadRequestException {
        LocalDate date = input.date() != null ? input.date()
                : settings.entryDate(person.getSheetId(), sheets.today(person.getSheetId()));
        RefuseClosedDate.refuse(person.getSheetId(), BuildClaim.dueBy(person, date, settings, holidays), periods);
    }
}

